/**
 * Python-style exception objects.
 *
 * The reference implementation is a CPython program, so a failing run prints a
 * traceback to stderr and exits with status 1. We mirror the exit status and the
 * final `<ExceptionType>: <message>` line, which is the part that carries
 * meaning. (The interpreter frame list and PyInstaller's `[PYI-<pid>:ERROR]`
 * banner reference Python source files and a per-run pid, so they cannot be
 * reproduced from JavaScript.)
 */

export class PyException extends Error {
  constructor(pyType, message) {
    super(message);
    this.pyType = pyType;
  }

  /** The last line of a CPython traceback. */
  toPythonLine() {
    return `${this.pyType}: ${this.message}`;
  }
}

export class PyValueError extends PyException {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyUnicodeEncodeError extends PyException {
  constructor(message) {
    super('UnicodeEncodeError', message);
  }
}

/**
 * Raised by the `int` argument converter. argparse catches this class of error
 * and turns it into `argument --f: invalid int value: '...'`, so it never
 * reaches the top level as a traceback.
 */
export class PyIntConversionError extends PyException {
  constructor(message) {
    super('ValueError', message);
  }
}

/**
 * Report an uncaught Python-level exception the way the interpreter does and
 * terminate with the interpreter's exit status.
 */
export function abortWithException(err) {
  if (err instanceof PyException) {
    process.stderr.write('Traceback (most recent call last):\n');
    process.stderr.write(`${err.toPythonLine()}\n`);
    process.exit(1);
  }
  throw err;
}

