/**
 * Helpers that reproduce the `str` semantics the reference program depends on:
 * whitespace stripping, code-point iteration, and the `\xHH` / `\uHHHH` /
 * `\U00HHHHHH` character escapes used in UnicodeEncodeError messages.
 */

/**
 * Code points for which Python's `str.isspace()` is true and which therefore
 * take part in `str.strip()` / `str.rstrip()`.
 */
const STR_WHITESPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20,
  0x85, 0xa0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
  0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

export function isStrWhitespace(codePoint) {
  return STR_WHITESPACE.has(codePoint);
}

/** `str.rstrip()` with no argument. */
export function strRstrip(s) {
  let end = s.length;
  while (end > 0) {
    // Whitespace is never astral, so inspecting one UTF-16 unit is enough.
    if (!isStrWhitespace(s.charCodeAt(end - 1))) break;
    end -= 1;
  }
  return s.slice(0, end);
}

/** `str.strip()` with no argument. */
export function strStrip(s) {
  let start = 0;
  let end = s.length;
  while (end > start && isStrWhitespace(s.charCodeAt(end - 1))) end -= 1;
  while (start < end && isStrWhitespace(s.charCodeAt(start))) start += 1;
  return s.slice(start, end);
}

/**
 * Split a string into code points. Python indexes strings by code point, so an
 * astral character counts as one position, not two UTF-16 units.
 */
export function toCodePoints(s) {
  const points = [];
  for (const ch of s) points.push(ch.codePointAt(0));
  return points;
}

/**
 * The escape Python embeds in a UnicodeEncodeError message for a single
 * offending character.
 */
export function escapeCodePoint(codePoint) {
  const hex = codePoint.toString(16);
  if (codePoint < 0x100) return `\\x${hex.padStart(2, '0')}`;
  if (codePoint < 0x10000) return `\\u${hex.padStart(4, '0')}`;
  return `\\U${hex.padStart(8, '0')}`;
}

