/**
 * Arbitrary-precision integer plumbing. Python ints are unbounded, so BigInt is
 * used for every value that crosses a base conversion.
 */

/** `int.from_bytes(v, byteorder='big')`. */
export function bytesToInt(bytes) {
  let acc = 0n;
  for (const b of bytes) acc = acc * 256n + BigInt(b);
  return acc;
}

/**
 * `divmod(a, b)` for positive `b`, using Python's floor semantics: the
 * remainder always takes the sign of the divisor. This differs from JavaScript's
 * `/` and `%` on negative values, and it is what makes the base-conversion
 * loops behave exactly as they do in Python.
 */
export function divmod(a, b) {
  let quotient = a / b;
  const remainder = a - quotient * b;
  if (remainder !== 0n && remainder < 0n) {
    quotient -= 1n;
    return [quotient, remainder + b];
  }
  return [quotient, remainder];
}

/** Big-endian base-256 digits of a non-negative int, most significant first. */
export function intToBytes(value) {
  const digits = [];
  let acc = value;
  while (acc > 0n) {
    const [quotient, remainder] = divmod(acc, 256n);
    digits.push(Number(remainder));
    acc = quotient;
  }
  digits.reverse();
  return digits;
}

