/**
 * Re-implementation of the `base58` package's public surface, derived from the
 * observed behaviour of the reference binary.
 *
 * Byte strings are plain arrays of integers in [0, 255] (see ./pybytes.mjs);
 * integers that cross a base conversion are BigInt, matching Python's unbounded
 * ints.
 */

import { PyValueError } from './errors.mjs';
import { bytesToInt, divmod } from './bigint.mjs';
import {
  asciiEncode,
  bytesEqual,
  bytesLstripByte,
  bytesRstrip,
  repeatByte,
} from './pybytes.mjs';
import { strRstrip } from './pystr.mjs';
import { sha256 } from './sha256.mjs';

export const BITCOIN_ALPHABET =
  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

const BASE = BigInt(BITCOIN_ALPHABET.length);

/** Byte value of the alphabet's first character — the "zero" digit, `1`. */
const ZERO_DIGIT = BITCOIN_ALPHABET.charCodeAt(0);

/** byte value -> digit value, for the decode direction. */
const DIGIT_VALUES = new Map();
for (let i = 0; i < BITCOIN_ALPHABET.length; i += 1) {
  DIGIT_VALUES.set(BITCOIN_ALPHABET.charCodeAt(i), i);
}

/**
 * Accept either a `str` or a byte string, as the library does. A `str` is
 * encoded with the ASCII codec, so non-ASCII input raises UnicodeEncodeError
 * rather than being silently transcoded.
 */
function scrubInput(v) {
  return typeof v === 'string' ? asciiEncode(v) : v;
}

/** `rstrip()` dispatched on the Python type, applied before ASCII encoding. */
function rstripAny(v) {
  return typeof v === 'string' ? strRstrip(v) : bytesRstrip(v);
}

/**
 * Encode a non-negative integer. `defaultOne` makes zero encode as the
 * single-digit `1` instead of the empty string, which is why
 * `b58encode_int(0)` is `b'1'` while `b58encode(b'\0')` is also `b'1'` — via a
 * different route.
 */
export function b58encodeInt(i, defaultOne = true) {
  if (i === 0n && defaultOne) return [ZERO_DIGIT];
  const digits = [];
  let acc = i;
  while (acc !== 0n) {
    const [quotient, index] = divmod(acc, BASE);
    digits.push(BITCOIN_ALPHABET.charCodeAt(Number(index)));
    acc = quotient;
  }
  digits.reverse();
  return digits;
}

/**
 * Decode base58 digits to an integer. Trailing whitespace is tolerated (the
 * library strips it); leading whitespace is not, and reports as an invalid
 * character.
 */
export function b58decodeInt(v) {
  const bytes = scrubInput(rstripAny(v));
  let decimal = 0n;
  for (const byte of bytes) {
    const value = DIGIT_VALUES.get(byte);
    if (value === undefined) {
      throw new PyValueError(`Invalid character '${String.fromCharCode(byte)}'`);
    }
    decimal = decimal * BASE + BigInt(value);
  }
  return decimal;
}

/**
 * Encode a byte string. Leading zero bytes are not part of the numeric value,
 * so they are stripped first and re-added as leading `1` digits, one per byte.
 */
export function b58encode(v) {
  const bytes = scrubInput(v);
  const origlen = bytes.length;
  const stripped = bytesLstripByte(bytes, 0x00);
  const newlen = stripped.length;

  const acc = bytesToInt(stripped);
  const encoded = b58encodeInt(acc, false);
  return repeatByte(ZERO_DIGIT, origlen - newlen).concat(encoded);
}

/**
 * Decode to a byte string — the inverse of {@link b58encode}, including the
 * leading `1` digit to zero byte correspondence. Note that trailing whitespace
 * is removed *before* the leading digits are counted.
 */
export function b58decode(v) {
  const bytes = scrubInput(rstripAny(v));
  const origlen = bytes.length;
  const stripped = bytesLstripByte(bytes, ZERO_DIGIT);
  const newlen = stripped.length;

  let acc = b58decodeInt(stripped);
  const result = [];
  while (acc > 0n) {
    const [quotient, mod] = divmod(acc, 256n);
    result.push(Number(mod));
    acc = quotient;
  }
  result.reverse();
  return repeatByte(0x00, origlen - newlen).concat(result);
}

/** First four bytes of the double SHA-256 of `bytes`. */
function checksum(bytes) {
  return sha256(sha256(bytes)).slice(0, 4);
}

/** Encode with a four-byte double-SHA-256 checksum appended to the payload. */
export function b58encodeCheck(v) {
  const bytes = scrubInput(v);
  return b58encode(bytes.concat(checksum(bytes)));
}

/** Decode and verify a checksummed value, returning the payload only. */
export function b58decodeCheck(v) {
  const decoded = b58decode(v);
  const payload = decoded.slice(0, -4);
  const check = decoded.slice(-4);
  if (!bytesEqual(check, checksum(payload))) {
    throw new PyValueError('Invalid checksum');
  }
  return payload;
}

