 *
 * Same delimiter rule as bytes: `'` unless the value contains a `'` and no `"`.
 * Printable non-ASCII characters are kept verbatim.
 */
export function reprStr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";

  let out = quote;
  for (const ch of s) {
    const codePoint = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === quote) out += `\\${quote}`;
    else if (codePoint === 0x20 || !NON_PRINTABLE.test(ch)) out += ch;
    else out += escapeCodePoint(codePoint);
  }
  return out + quote;
}

