import { basename } from 'node:path';

import { ArgumentParser } from './lib/argparse.mjs';
import * as base58 from './lib/base58.mjs';
import { abortWithException } from './lib/errors.mjs';
import { reprBytes, utf8Encode } from './lib/pybytes.mjs';

const parser = new ArgumentParser(basename(process.argv[1]));
parser.addArgument('a', { type: 'str', required: true });
parser.addArgument('b', { type: 'str', required: true });
parser.addArgument('c', { type: 'str', required: true });
parser.addArgument('d', { type: 'str', required: true });
parser.addArgument('e', { type: 'str', required: true });
parser.addArgument('f', { type: 'int', required: true });
parser.addArgument('g', { type: 'int', required: true });
const args = parser.parseArgs(process.argv.slice(2));

/** `print()` of a bytes object. */
function printBytes(value) {
  process.stdout.write(`${reprBytes(value)}\n`);
}

/** `print()` of an int. */
function printInt(value) {
  process.stdout.write(`${value}\n`);
}

try {
  // 最终复杂场景：多个API组合调用
  const enc1 = base58.b58encode(utf8Encode(args.a)); // 基本编码1
  const dec1 = base58.b58decode(args.b); // 基本解码1
  const encCheck1 = base58.b58encodeCheck(utf8Encode(args.c)); // 校验和编码1
  const decCheck1 = base58.b58decodeCheck(encCheck1); // 校验和解码1
  const encInt1 = base58.b58encodeInt(args.f); // 整数编码1
  const decInt1 = base58.b58decodeInt(encInt1); // 整数解码1
  const enc2 = base58.b58encode(utf8Encode(args.d)); // 基本编码2
  const dec2 = base58.b58decode(args.e); // 基本解码2
  const encInt2 = base58.b58encodeInt(args.g); // 整数编码2
  const encCheck2 = base58.b58encodeCheck(dec1); // 对解码结果进行校验和编码
  const decCheck2 = base58.b58decodeCheck(encCheck2); // 校验和解码2
  const enc3 = base58.b58encode(decCheck2); // 对校验和解码结果进行基本编码
  printBytes(enc1);
  printBytes(dec1);
  printBytes(encCheck1);
  printBytes(decCheck1);
  printBytes(encInt1);
  printInt(decInt1);
  printBytes(enc2);
  printBytes(dec2);
  printBytes(encInt2);
  printBytes(encCheck2);
  printBytes(decCheck2);
  printBytes(enc3);
} catch (err) {
  abortWithException(err);
}

