import { execFileSync, spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test20_executable';
const B58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

function run(cmd, argv) {
  const r = spawnSync(cmd, argv, { encoding: 'utf8', timeout: 30000 });
  const errLines = (r.stderr || '').trimEnd().split('\n');
  // Last meaningful stderr line, ignoring PyInstaller's per-run banner.
  const last = errLines.filter((l) => !l.startsWith('[PYI-')).pop() || '';
  return { out: r.stdout, code: r.status, err: last };
}

function rnd(n) { return Math.floor(Math.random() * n); }
function pick(a) { return a[rnd(a.length)]; }

function randB58(len) {
  let s = '';
  for (let i = 0; i < len; i += 1) s += B58[rnd(58)];
  return s;
}
function randStr(len) {
  let s = '';
  for (let i = 0; i < len; i += 1) s += String.fromCharCode(rnd(0x7f - 0x20) + 0x20);
  return s;
}
function randBinStr(len) {
  let s = '';
  for (let i = 0; i < len; i += 1) s += String.fromCharCode(rnd(0x100));
  return s;
}

const INT_FORMS = ['0', '1', '57', '58', '59', '3363', '1000000', '82019528', '2147483647',
  '4294967295', '9007199254740993', '123456789012345678901234567890123456789',
  ' 42 ', '+7', '007', '1_000', '1_0_0', String(rnd(1e9)), String(rnd(1e9))];

const STR_FORMS = () => [
  '', 'x', 'Test123', '@#$%^&*()', "it's", 'say "hi"', 'both\' and "', 'back\\slash',
  'tab\there', 'a', '中文测试', 'héllo', '😀 emoji', '1234567890',
  'A'.repeat(30), 'a'.repeat(50), ' leading', 'trailing ', randStr(rnd(40)),
  randStr(rnd(40)), randBinStr(rnd(20)), randB58(rnd(40)),
];

const B58_FORMS = () => [
  '', '1', '11', '111z', 'z', 'Z', '28', '2', 'A', 'VLKw',
  '79KKvfsXwLkag2r3FrZNPdWKv4pvT8DVk', 'z   ', 'z\t\n', '1 ', '1'.repeat(10),
  randB58(rnd(50)), randB58(rnd(50)), randB58(1 + rnd(80)),
  // invalid / error-triggering
  '0', 'O', 'I', 'l', ' z', 'hello world!', '中', 'é', '-', 'zz zz',
];

let pass = 0;
const failures = [];

function check(argv, label) {
  const mine = run('node', ['/output/test20.mjs', ...argv]);
  const theirs = run(EXE, argv);
  const okOut = mine.out === theirs.out;
  const okCode = mine.code === theirs.code;
  const okErr = mine.err === theirs.err;
  if (okOut && okCode && okErr) { pass += 1; return; }
  failures.push({ label, argv, mine, theirs, okOut, okCode, okErr });
}

// --- exhaustive-ish structured sweep -----------------------------------------
const strs = STR_FORMS();
const b58s = B58_FORMS();
for (const b of b58s) {
  check(['--a', 'x', '--b', b, '--c', 'x', '--d', 'x', '--e', 'z', '--f', '1', '--g', '1'], `b=${JSON.stringify(b)}`);
}
for (const e of b58s) {
  check(['--a', 'x', '--b', 'z', '--c', 'x', '--d', 'x', '--e', e, '--f', '1', '--g', '1'], `e=${JSON.stringify(e)}`);
}
for (const s of strs) {
  check(['--a', s, '--b', 'z', '--c', s, '--d', s, '--e', 'z', '--f', '1', '--g', '1'], `str=${JSON.stringify(s)}`);
}
for (const f of INT_FORMS) {
  check(['--a', 'x', '--b', 'z', '--c', 'x', '--d', 'x', '--e', 'z', '--f', f, '--g', f], `f=${JSON.stringify(f)}`);
}

// --- random combinations -----------------------------------------------------
for (let i = 0; i < 120; i += 1) {
  const s = STR_FORMS();
  const v = B58_FORMS();
  check([
    '--a', pick(s), '--b', pick(v), '--c', pick(s), '--d', pick(s),
    '--e', pick(v), '--f', pick(INT_FORMS), '--g', pick(INT_FORMS),
  ], `random#${i}`);
}

// --- argparse surface --------------------------------------------------------
const OK = ['--a', 'x', '--b', 'z', '--c', 'x', '--d', 'x', '--e', 'z', '--f', '1', '--g', '1'];
const argvCases = [
  ['--help'], ['-h'], ['--h'], ['-h', '--a', 'x'], [],
  ['--f', '1', '--g', '1'],
  ['--a', 'x', '--b', 'z', '--c', 'x', '--d', 'x', '--f', '1', '--g', '1'],
  [...OK, '--z', '9'], [...OK, 'extra'], [...OK, '--z', '9', 'pos1'],
  [...OK, '--'], [...OK, '--', '--'],
  ['--a', 'x', '--', '--b', 'z', '--c', 'x', '--d', 'x', '--e', 'z', '--f', '1', '--g', '1'],
  ['--a', 'x', '--b', 'z', '--c', 'x', '--d', 'x', '--e', 'z', '--f', '1', '--g'],
  ['--a', 'x', '--b', 'z', '--c', 'x', '--d', 'x', '--e', 'z', '--f', '1'],
