  ['--a', 'x', '--b', 'z', '--c', 'x', '--d', 'x', '--e', 'z', '--f', '_1', '--g', '1'],
  ['--a', 'x', '--b', 'z', '--c', 'x', '--d', 'x', '--e', 'z', '--f', '1_', '--g', '1'],
  ['--a', 'x', '--b', 'z', '--c', 'x', '--d', 'x', '--e', 'z', '--f', '1__0', '--g', '1'],
