  ['--a', '-', '--b', 'z', '--c', 'x', '--d', 'x', '--e', 'z', '--f', '1', '--g', '1'],
  ['--a', '--b', '--b', 'z', '--c', 'x', '--d', 'x', '--e', 'z', '--f', '1', '--g', '1'],
];
for (const argv of argvCases) check(argv, `argv=${JSON.stringify(argv)}`);

console.log(`\npassed: ${pass}, failed: ${failures.length}`);
for (const f of failures.slice(0, 12)) {
