 * makes an exception for negative numbers (no option here looks like one) and
 * for anything containing a space.
 */
#looksLikeOption(token) {
  if (!token.startsWith('-')) return false;
  if (token === '-' || token === '--') return true;
  if (NEGATIVE_NUMBER.test(token)) return false;
  if (token.includes(' ')) return false;
  return true;
}

