/**
 * Whether a token would be read as an option rather than a value, following
 * argparse's `_parse_optional`. A bare `-`, a negative number (no option here
 * looks like one) and anything containing a space are all values; `--` is
 * neither — it is the positional separator and cannot be consumed as a value.
 */
#looksLikeOption(token) {
  if (token === '') return false;
  if (!token.startsWith('-')) return false;
  if (token === '--') return true;
  if (this.#lookupOption(token.split('=')[0])) return true;
  if (token.length === 1) return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  if (token.includes(' ')) return false;
  return true;
}

