 * abbreviation, and argparse's exact usage/error text and exit codes.
 *
 * Error precedence matches CPython: a type-conversion failure is reported while
 * the option is being consumed, missing required options are reported next, and
 * unrecognized arguments last.
 */

import { PyIntConversionError } from './errors.mjs';
import { pyInt } from './pyint.mjs';
import { reprStr } from './pystr.mjs';

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.actions = [];
  }

  /**
   * Register `--name`. `type` is `'str'` or `'int'`; the metavar argparse
   * derives from the destination is the upper-cased name.
   */
  addArgument(name, { type = 'str', required = false } = {}) {
    this.actions.push({
      name,
      option: `--${name}`,
      metavar: name.toUpperCase(),
      type,
      required,
    });
    return this;
  }

  formatUsage() {
    const parts = this.actions.map((a) => `${a.option} ${a.metavar}`);
    return `usage: ${this.prog} [-h] ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = ['-h, --help', ...this.actions.map((a) => `${a.option} ${a.metavar}`)];
    // argparse aligns the help column at 2 + <widest invocation> + 2.
    const width = Math.max(...invocations.map((s) => s.length));

    let out = `${this.formatUsage()}\noptions:\n`;
    out += `  ${'-h, --help'.padEnd(width)}  show this help message and exit\n`;
    for (const action of this.actions) {
      out += `  ${action.option} ${action.metavar}\n`;
    }
    return out;
  }

  /** Print usage plus `prog: error: message` to stderr and exit 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  exitWithHelp() {
    process.stdout.write(this.formatHelp());
    process.exit(0);
  }

  /**
   * Resolve a token to a registered option, allowing unambiguous prefix
   * abbreviation the way argparse does. Returns `undefined` when nothing
   * matches, `null` when the prefix is ambiguous.
   */
  #lookupOption(token) {
    const options = ['-h', '--help', ...this.actions.map((a) => a.option)];
    if (options.includes(token)) return token;
    if (!token.startsWith('--')) return undefined;
    const matches = options.filter((o) => o.startsWith('--') && o.startsWith(token));
    if (matches.length === 1) return matches[0];
    if (matches.length > 1) return null;
    return undefined;
  }

  /**
   * Whether a token would be read as an option rather than a value. argparse
   * makes an exception for negative numbers (no option here looks like one) and
   * for anything containing a space.
   */
  #looksLikeOption(token) {
    if (!token.startsWith('-')) return false;
    if (token === '-' || token === '--') return true;
    if (NEGATIVE_NUMBER.test(token)) return false;
    if (token.includes(' ')) return false;
    return true;
  }

  #convert(action, raw) {
    if (action.type !== 'int') return raw;
    try {
      return pyInt(raw);
    } catch (err) {
      if (err instanceof PyIntConversionError) {
        this.error(`argument ${action.option}: invalid int value: ${reprStr(raw)}`);
      }
      throw err;
    }
  }

  parseArgs(argv) {
    const values = new Map();
    const extras = [];
    let onlyPositionals = false;

    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];

      // This argparse keeps `--` itself as an unrecognized argument, and treats
      // everything after it as positional.
      if (onlyPositionals || token === '--') {
        if (token === '--') onlyPositionals = true;
        extras.push(token);
        continue;
      }

      let name = token;
      let inlineValue;
      if (token.startsWith('--') && token.includes('=')) {
        const split = token.indexOf('=');
        name = token.slice(0, split);
        inlineValue = token.slice(split + 1);
      }

      const option = this.#lookupOption(name);
      if (option === null) {
        this.error(`ambiguous option: ${name} could match ${this.actions.map((a) => a.option).join(', ')}`);
      }
      if (option === undefined) {
        extras.push(token);
        continue;
      }
      if (option === '-h' || option === '--help') this.exitWithHelp();

      const action = this.actions.find((a) => a.option === option);
      let raw = inlineValue;
      if (raw === undefined) {
        const next = argv[i + 1];
        if (next === undefined || this.#looksLikeOption(next)) {
          this.error(`argument ${action.option}: expected one argument`);
        }
        raw = next;
        i += 1;
      }
      // Conversion happens as the option is consumed, so a bad value is
      // reported before any missing-argument complaint.
      values.set(action.name, this.#convert(action, raw));
    }

    const missing = this.actions.filter((a) => a.required && !values.has(a.name));
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing.map((a) => a.option).join(', ')}`,
      );
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return Object.fromEntries(values);
  }
}

